<?php
declare(strict_types=1);
require_once __DIR__ . '/../admin-auth.php';
require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $id=(int)($_POST['id']??0); if(($_POST['action']??'')==='hide') db()->prepare('UPDATE products SET is_active=0 WHERE id=?')->execute([$id]); elseif(($_POST['action']??'')==='unhide') db()->prepare('UPDATE products SET is_active=1 WHERE id=?')->execute([$id]); elseif(($_POST['action']??'')==='delete') db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]); header('Location: products.php'); exit; }
$products=db()->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products Admin</title><link rel="stylesheet" href="../style.css?v=9"><script src="../app.js?v=9" defer></script></head><body><header class="site-header"><a class="brand" href="index.php">Sanderi <span>Admin</span></a><nav class="nav"><a href="index.php">Dashboard</a><a class="active-menu" href="products.php">Products</a><a href="product-form.php">Add product</a><a href="orders.php">Orders</a><a href="../admin-logout.php">Logout</a></nav></header><main class="page-shell"><h1>Products</h1><div class="admin-table"><div class="table-head"><span>Name</span><span>Category</span><span>Price</span><span>Stock</span><span>Action</span></div><?php foreach($products as $product): ?><div class="table-row"><span><?= htmlspecialchars($product['name']) ?><?php if(!$product['is_active']): ?><small class="hidden-label">Hidden</small><?php endif; ?></span><span><?= htmlspecialchars($product['category_name']??'-') ?></span><span>₹<?= number_format((float)$product['price'],2) ?></span><span><?= $product['stock'] ?></span><div class="admin-actions"><a class="admin-action edit-action" href="product-form.php?id=<?= $product['id'] ?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $product['id'] ?>"><input type="hidden" name="action" value="<?= $product['is_active'] ? 'hide' : 'unhide' ?>"><button class="admin-action <?= $product['is_active'] ? 'hide-action' : 'unhide-action' ?>"><?= $product['is_active'] ? 'Hide' : 'Unhide' ?></button></form><form method="post" onsubmit="return confirm('Permanently delete this product?');"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $product['id'] ?>"><input type="hidden" name="action" value="delete"><button class="admin-action delete-action">Delete</button></form></div></div><?php endforeach; ?></div></main></body></html>
